 assert.equal(tree.parseDiagnostics.length,0,path);
 const add=(node:any)=>{if(node&&(ts.isStringLiteral(node)||ts.isNoSubstitutionTemplateLiteral(node)))imports.push(node.text);};
 const visit=(node:any)=>{if((ts.isImportDeclaration(node)||ts.isExportDeclaration(node))&&node.moduleSpecifier)add(node.moduleSpecifier);if(ts.isCallExpression(node)&&node.arguments?.length===1&&(node.expression.kind===ts.SyntaxKind.ImportKeyword||ts.isIdentifier(node.expression)&&node.expression.text==="require"))add(node.arguments[0]);ts.forEachChild(node,visit);};visit(tree);
 return[...new Set(imports)];
}
